previewCss:
.darma-loader-darma-b7-rising-bubbles { --accent: var(--loader-color, #22d3ee); width: var(--loader-size, 76px); height: var(--loader-size, 76px); position: relative; }
.darma-loader-darma-b7-rising-bubbles span { position: absolute; bottom: 0; width: calc(var(--loader-size, 76px) * .16); height: calc(var(--loader-size, 76px) * .16); border-radius: 50%; background: radial-gradient(circle at 35% 30%, color-mix(in srgb, #fff 65%, transparent), var(--accent)); opacity: 0; animation: darma-loader-darma-b7-rising-bubbles-rise calc(var(--loader-speed, 1s) * 2.2) ease-in infinite; }
.darma-loader-darma-b7-rising-bubbles span:nth-child(1) { left: 8%; animation-delay: 0s; }
.darma-loader-darma-b7-rising-bubbles span:nth-child(2) { left: 28%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b7-rising-bubbles span:nth-child(3) { left: 48%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b7-rising-bubbles span:nth-child(4) { left: 68%; animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
.darma-loader-darma-b7-rising-bubbles span:nth-child(5) { left: 86%; animation-delay: calc(var(--loader-speed, 1s) * 1.6); }
@keyframes darma-loader-darma-b7-rising-bubbles-rise { 0% { transform: translateY(0) scale(.4); opacity: 0; } 20% { opacity: .9; } 80% { opacity: .9; } 100% { transform: translateY(calc(var(--loader-size, 76px) * -.9)) scale(1); opacity: 0; } }

